// Extraer información del email de Idealista
const emailBody = $input.item.json.body || '';
const subject = $input.item.json.subject || '';

// Regex patterns para extraer datos
const precioRegex = /(\d{1,3}(?:\.\d{3})*(?:,\d{2})?\s*€)/;
const metrosRegex = /(\d+)\s*m²/;
const direccionRegex = /(?:Dirección|Ubicación):\s*([^\n]+)/i;
const ciudadRegex = /(?:Ciudad|Localidad):\s*([^\n]+)/i;
const tipoRegex = /(piso|casa|chalet|apartamento|estudio|ático|dúplex|local)/i;

// Buscar enlace al anuncio
const enlaceRegex = /(https:\/\/www\.idealista\.com\/inmueble\/\d+)/;

// Extraer datos
const precioMatch = emailBody.match(precioRegex);
const metrosMatch = emailBody.match(metrosRegex);
const direccionMatch = emailBody.match(direccionRegex) || subject.match(/en\s+([^,]+)/);
const ciudadMatch = emailBody.match(ciudadRegex) || subject.match(/,\s*([A-Z][a-zá-ú]+)/);
const tipoMatch = emailBody.match(tipoRegex) || subject.match(tipoRegex);
const enlaceMatch = emailBody.match(enlaceRegex);

// Limpiar precio (convertir de formato español a número)
let precio = null;
if (precioMatch) {
  const precioStr = precioMatch[1].replace(/\./g, '').replace(',', '.').replace('€', '').trim();
  precio = parseFloat(precioStr);
}

// Preparar datos para el CRM
const propertyData = {
  direccion: direccionMatch ? direccionMatch[1].trim() : 'Dirección no especificada',
  ciudad: ciudadMatch ? ciudadMatch[1].trim() : 'Madrid', // Default
  tipo: tipoMatch ? tipoMatch[1].toLowerCase() : 'piso', // Default
  precio: precio || 0,
  metros: metrosMatch ? parseInt(metrosMatch[1]) : 0,
  portal: 'Idealista',
  enlace: enlaceMatch ? enlaceMatch[1] : '',
  estado: 'nueva',
  notas: `Propiedad captada automáticamente desde email de Idealista.\n\nAsunto: ${subject}`,
  fecha_creacion: new Date().toISOString()
};

// Validación mínima
if (!propertyData.precio || !propertyData.metros) {
  return [{
    json: {
      error: true,
      message: 'No se pudieron extraer datos suficientes del email',
      emailSubject: subject,
      rawData: propertyData
    }
  }];
}

return [{
  json: {
    success: true,
    property: propertyData,
    emailSubject: subject,
    emailDate: $input.item.json.date
  }
}];

